assert '\nRARITIES = ["Common", "Uncommon", "Rare", "Epic", "Legendary", "Mythic"]\n' in _ps, "SkyyPets' rarity order changed"
assert ('\nRARITY_COLORS = [SUI.QUALITY["Common"], SUI.QUALITY["Uncommon"], SUI.QUALITY["Rare"], SUI.QUALITY["Epic"], SUI.QUALITY["Legendary"],\n'
        '                 SUI.RARITY["Mythic"]]\n') in _ps, "SkyyPets' RARITY_COLORS changed"
assert 'PORTRAIT_ID = dict((k[0], "Skyy_PetIcon_" + k[0]) for k in KINDS)' in _ps and '_iid = "%s_%s" % (PORTRAIT_ID[_k], _r)' in _ps, \
    "SkyyPets' rarity portrait ids are no longer Skyy_PetIcon_<Kind>_<Rarity>"
assert '\nRBG_ALPHA = "0.4"\nRBG_NONE = SUI.COLOR["disabled"] + "(0.15)"\n' in _ps, "SkyyPets' rarity square colours (RBG_ALPHA / RBG_NONE) changed"
del _ps

